	qid=allQuestions[qidlabel]
	qidType=qid.o.xmlTagName
	if qid.cols and qid.rows:
		qidType+='grid'
	return 	qidType

def clearForm(question):
	if question.cols:
		for x in question.rows:
			for y in question.cols:
				question[x][y].val = None	
	elif not questions.cols:
			for x in question.rows:				
				question[x].val = None
